// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool success;
        // We use try/catch to handle the possibility of the call reverting
        // In the reference, for any valid input that does not revert, it returns true
        // The bug returns false, so we assert that the return value is true when the call succeeds
        try c.transfer(_tos, v) returns (bool result) {
            success = true;
            assertTrue(result, "transfer should return true on success");
        } catch {
            // If it reverts, we don't assert anything
        }
    }
}

